package com.myles.kotobafloat;

import android.content.*;
import android.database.sqlite.*;
import org.json.*;
import java.io.*;
import java.time.*;
import java.util.*;

final class Feature17Tests {
    private int checks;
    private void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
    static int run(Context target)throws Exception{return new Feature17Tests().test(target);}
    private int test(Context target)throws Exception{
        File file=new File(target.getCacheDir(),"features-1.7.db"),files=new File(target.getCacheDir(),"features-1.7-files");files.mkdirs();for(File f:files.listFiles())if(!f.delete())throw new IOException("Cannot clean isolated fixture");SQLiteDatabase.deleteDatabase(file);
        Context isolated=new ContextWrapper(target){@Override public File getDatabasePath(String n){return file;}@Override public File getFilesDir(){return files;}@Override public SharedPreferences getSharedPreferences(String n,int mode){return target.getSharedPreferences("features-1.7",mode);}};
        isolated.getSharedPreferences("preferences",0).edit().clear().commit();java.lang.reflect.Constructor<WordStore> ctor=WordStore.class.getDeclaredConstructor(Context.class);ctor.setAccessible(true);WordStore store=ctor.newInstance(isolated);java.lang.reflect.Field field=WordStore.class.getDeclaredField("db");field.setAccessible(true);SQLiteDatabase db=(SQLiteDatabase)field.get(store);Prefs p=new Prefs(isolated);
        try{
            List<Word> words=store.words("N5","","all",false,false,4);Word a=words.get(0),b=words.get(1);String base=StudySession.baseScope(p);
            String oldGroupScope=base.replace("|OFF|","|SIZE|"),oldGroup=new StudyGroup(Arrays.asList(a.id,b.id),"",oldGroupScope,20).save();p.put("group.state",oldGroup);p.put("currentId",a.id);p.put("queue.state","legacy-queue");ScopeMemory.migrate(p);check(ScopeMemory.position(p,base,base,false,"id").equals(a.id)&&ScopeMemory.group(p,oldGroupScope).equals(oldGroup),"Legacy current word and last stored group are adopted once, even when grouping is off");
            ScopeMemory.save(p,base,base,false,a.id,"");p.put("level","N4");String n4=StudySession.baseScope(p);check(ScopeMemory.position(p,n4,n4,false,"id").isEmpty(),"New range does not borrow another range position");ScopeMemory.save(p,n4,n4,false,b.id,"");check(ScopeMemory.position(p,base,base,false,"id").equals(a.id)&&ScopeMemory.position(p,n4,n4,false,"id").equals(b.id),"Each range retains its own position");ScopeMemory.save(p,base,base,true,b.id,"shuffled");check(ScopeMemory.position(p,base,base,false,"id").equals(a.id),"Sequential and shuffled positions stay independent");ScopeMemory.validate(p.data.getString("scopeMemory",""));check(BackupSettings.export(p.data).has("scopeMemory"),"Scoped history is included in full backup");
            ReviewDraft d=new ReviewDraft("test-scope","TASK",false,Arrays.asList(a.id,b.id,words.get(2).id,words.get(3).id));store.startDraft(d);ReviewDraft reveal=d.copy();reveal.revealed=true;d=store.saveDraft(d,reveal,null,-1);check(store.draft("TASK").revealed,"Reveal state survives an activity/process restart");
            ReviewDraft next=d.copy();next.session.answer(0,true);next.missed++;next.revealed=false;ReviewDraft advanced=store.saveDraft(d,next,a,0);JSONObject once=new JSONObject(store.backup());check(advanced.session.position==1&&advanced.session.queue.size()==5,"Rating persists both advance and bounded retry");store.saveDraft(d,next,a,0);JSONObject twice=new JSONObject(store.backup());check(once.getJSONArray("review_days").toString().equals(twice.getJSONArray("review_days").toString()),"Replaying an old rating token never scores twice");check(store.draft("TASK").revision==advanced.revision,"Stale checkpoint cannot move the cursor backwards");
            String prior=store.backup();ReviewDraft failed=advanced.copy();failed.session.answer(0,true);failed.missed++;
            db.execSQL("CREATE TRIGGER fail_checkpoint BEFORE INSERT ON review_drafts BEGIN SELECT RAISE(ABORT,'injected checkpoint failure');END");try{store.saveDraft(advanced,failed,b,0);throw new AssertionError("Injected transaction unexpectedly committed");}catch(SQLiteException expected){}finally{db.execSQL("DROP TRIGGER fail_checkpoint");}
            JSONObject unchanged=new JSONObject(store.backup());check(unchanged.getJSONArray("reviews").toString().equals(new JSONObject(prior).getJSONArray("reviews").toString())&&unchanged.getJSONArray("weak_words").toString().equals(new JSONObject(prior).getJSONArray("weak_words").toString()),"Checkpoint write failure rolls back rating and weak evidence together");check(store.draft("TASK").session.position==1,"Failed transaction keeps original batch cursor");
            store.favorite(a,true);String old=store.backup();store.favorite(a,false);store.restore(old);check(!store.byId(a.id).favorite,"An older timed backup cannot resurrect a cancelled favorite");store.familiar(a,true);String oldFamiliar=store.backup();store.familiar(a,false);store.restore(oldFamiliar);check(!store.byId(a.id).familiar,"An older timed backup cannot resurrect a cancelled familiar mark");
            JSONObject legacy=new JSONObject(old);legacy.remove("mark_changes");db.delete("mark_changes",null,null);store.restore(legacy.toString(),false,true);check(!store.byId(a.id).favorite,"Legacy conflict option can preserve local flags");store.restore(legacy.toString(),false,false);check(store.byId(a.id).favorite,"Legacy merge option explicitly unions selected flags");
            p.put("wordSize",30);store.restore(old,false,true);check(p.wordSize()==30,"Records-only restore does not replace settings");
            JSONObject invalid=new JSONObject(store.backup());JSONArray badMarks=new JSONArray().put(new JSONObject().put("id",a.id).put("field","favorite,seen=9").put("value",1).put("changed_at",1));invalid.put("mark_changes",badMarks);String beforeBad=store.backup();try{store.restore(invalid.toString());throw new AssertionError("Invalid mark accepted");}catch(IllegalArgumentException expected){}check(new JSONObject(store.backup()).getJSONArray("progress").toString().equals(new JSONObject(beforeBad).getJSONArray("progress").toString()),"Invalid mark fields fail before record writes");
            p.data.edit().putString("private.fixture","preserve-me").putLong("backup.savedAt",42).commit();String snapshot=store.localSnapshot();boolean originalFavorite=store.byId(a.id).favorite;
            JSONObject incoming=new JSONObject(store.backup());incoming.getJSONObject("preferences").put("wordSize",20);RestoreSafety.apply(isolated,store,incoming.toString(),true,true);check(p.wordSize()==20&&RestoreSafety.available(isolated),"Import records a private snapshot before applying settings");check(store.draft("TASK")==null,"Restore invalidates unfinished batches without losing ratings");
            store.favorite(a,!originalFavorite);RestoreSafety.undo(isolated,store);check(store.byId(a.id).favorite==originalFavorite&&p.wordSize()==30&&p.data.getLong("backup.savedAt",0)==42&&p.data.getString("private.fixture","").equals("preserve-me"),"Undo restores exact records and typed local preferences");check(store.draft("TASK")!=null&&store.draft("TASK").session.position==1,"Undo restores pre-import batch checkpoint");
            RestoreSafety.apply(isolated,store,incoming.toString(),true,true);File pending=new File(files,"restore-"+Integer.toHexString(file.getAbsolutePath().hashCode())+"-pending.json");try(FileOutputStream output=new FileOutputStream(pending)){output.write("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));output.getFD().sync();}RestoreSafety.recover(isolated,store);check(p.wordSize()==30&&!pending.exists(),"Interrupted restore journal returns to the exact pre-import snapshot");
            LocalDate end=LocalDate.now();db.delete("review_days",null,null);db.execSQL("INSERT INTO review_days VALUES (?,?,?,?,?)",new Object[]{end.minusDays(6).toString(),a.id,2,1,1});db.execSQL("INSERT INTO review_days VALUES (?,?,?,?,?)",new Object[]{end.minusDays(7).toString(),a.id,20,10,10});db.execSQL("INSERT INTO review_days VALUES (?,?,?,?,?)",new Object[]{end.plusDays(1).toString(),a.id,30,20,10});long[] week=store.weekly(Collections.singletonList(a),end);check(week[1]==1&&week[2]==2,"Seven-day recap includes boundary day and excludes older/future records");
            check(PitchPattern.morae("きゃっとーん").equals(Arrays.asList("きゃ","っ","と","ー","ん")),"Mora segmentation counts contracted kana, small tsu, long vowel and nasal correctly");check(PitchPattern.morae("communication").isEmpty()&&PitchPattern.morae("あい／あう").isEmpty(),"Unreliable source readings never get a guessed plot");check(PitchPattern.accents("⓪③",3).equals(Arrays.asList(0,3))&&PitchPattern.accents("④",3).isEmpty(),"Multiple source accents remain alternatives and impossible positions are rejected");check(!PitchPattern.high(0,0)&&PitchPattern.high(1,0)&&PitchPattern.high(0,1)&&!PitchPattern.high(1,1),"Basic pitch contour distinguishes flat and initial-drop patterns");
            Word energy=store.words("ALL","エネルギー","all",false,false,10).stream().filter(w->w.word.equals("エネルギー")).findFirst().get();check(Pronunciation.origin(energy.reading)&&energy.spokenForm().equals("エネルギー"),"Foreign etymology is retained but Japanese TTS uses the original kana headword");
            check(Pronunciation.spoken("漢字","English").isEmpty(),"Unreliable non-kana origin does not become guessed Japanese speech");
            File blocked=new File(files,"blocked");blocked.createNewFile();Context cannotSnapshot=new ContextWrapper(isolated){@Override public File getFilesDir(){return blocked;}};String beforeFailure=store.backup();try{RestoreSafety.apply(cannotSnapshot,store,incoming.toString(),true,true);throw new AssertionError("Import without snapshot accepted");}catch(IOException expected){}check(new JSONObject(store.backup()).getJSONArray("progress").toString().equals(new JSONObject(beforeFailure).getJSONArray("progress").toString())&&p.wordSize()==30,"Unwritable snapshot destination prevents all import changes");
            try{ScopeMemory.validate("{\"scope\":{\"positions\":1}}");throw new AssertionError("Invalid scope history accepted");}catch(JSONException expected){}check(true,"Malformed scoped history is rejected before restoration");
            for(int i=0;i<65;i++)ScopeMemory.group(p,"range-"+i,"group-"+i);JSONObject bounded=new JSONObject(p.data.getString("scopeMemory","{}"));check(bounded.length()<=48&&bounded.has("range-64"),"Group-only history stays bounded and retains the latest range");
            List<Word> full=store.words("ALL","","all",false,false,0);Map<String,String> pool=new LinkedHashMap<>();for(Word w:full)pool.put(w.id,w.word+w.reading);String queue=new ShuffleDeck(pool,"","full-deck").save(),group=new StudyGroup(pool.keySet(),"","full-deck",10641).save();p.put("customWords",String.join("\n",pool.keySet()));p.put("group.state",group);for(int i=0;i<8;i++)ScopeMemory.save(p,"large-"+i,"full-deck",true,a.id,queue);BackupSettings.validate(BackupSettings.export(p.data));check(p.data.getString("scopeMemory","").length()<=2000000,"Multiple full-deck histories still produce a restorable backup within the settings limit");
            return checks;
        }finally{db.close();SQLiteDatabase.deleteDatabase(file);isolated.getSharedPreferences("preferences",0).edit().clear().commit();for(File f:files.listFiles())f.delete();files.delete();}
    }
}
